          const newFrame: CanvasItem = { id: crypto.randomUUID(), type: ItemType.FRAME, x: minX - padding, y: minY - padding, width: (maxX - minX) + padding * 2, height: (maxY - minY) + padding * 2, rotation: 0, content: '新组合画框', status: 'empty' };
