egments([]); setPropertyPanelView({ view: 'main', ts: Date.now() }); }} initialView={propertyPanelView} onFrameAction={handleFrameAction} editTool={editTool} setEditTool={setEditTool} brushSize={brushSize} setBrushSize={setBrushSize} onApplyEdit={handleApplyEdit} onClearMask={() => canvasRef.current?.clearMask()} onJSONAnalysis={handleJSONAnalysis} isAnalyzingJSON={isAnalyzingJSON} onStartPickPoint={(nid, temp) => handleGenerate(nid, '__START_PICK_POINT__', { artisticLevel: temp })} isPickingPoint={isPickingPoint} currentEvolutionLevel={currentEvolutionLevel} isCncMode={isCncMode} setIsCncMode={setIsCncMode} onUpdatePoint={handleUpdatePoint} onClearAllPoints={handleClearAllPoints} onCommitPointChanges={handleCommitPointChanges} onAutoAlign={handleAutoAlignPoints} onClosePanel={() => { setIsPropertiesPanelOpen(false); setEditMode(false); setPropertyPanelView({ view: 'main', ts: Date.now() }); }} onFloatingAction={handleFloatingAction} /> </div> </div> </div>
