                temperature: temperature, 
                responseSchema: {
                    type: Type.ARRAY,
                    items: {
                        type: Type.OBJECT,
                        properties: {
                            point: { 
                                type: Type.ARRAY, 
                                items: { type: Type.NUMBER },
