const sleep = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));
const VALID_ASPECT_RATIOS = ['1:1', '3:4', '4:3', '9:16', '16:9'];

const PERSPECTIVE_LOCK = `[PERSPECTIVE LOCK PROTOCOL]: 
1. Maintain the EXACT 3D camera orientation, elevation, and azimuth of the reference image. 
2. The object must remain in the same spatial bounding box. 
3. DO NOT introduce any rotation, camera shift, or perspective changes. 
4. The structural alignment must be 100% consistent with the reference.`;

const MASKED_INPAINTING_PROTOCOL = `[MASKED_RE-RENDERING_SYSTEM_PROTOCOL]:
1. INPUT_FILE_0: SOURCE_IMAGE (Original Context).
2. INPUT_FILE_1: BINARY_MASK (High-Contrast Reference).
3. MANDATE: This is a pixel-perfect in-painting task.
4. SPATIAL CONSTRAINT: You are ONLY permitted to modify pixels where INPUT_FILE_1 is WHITE (#FFFFFF).
5. PROTECTION: Any pixel modification where INPUT_FILE_1 is BLACK (#000000) is a FAILURE. Treat black areas as a read-only immutable layer.
6. CONTINUITY: Ensure lighting, material transitions, and shadow casting within the white region integrate perfectly with the surrounding black region context.
7. INSTRUCTION: `;

const TOPOLOGY_VARIATION_PROTOCOL = `[TOPOLOGY-PRESERVED SEMANTIC MUTATION]:
1. IMMUTABLE ELEMENTS: Category, Topology (Basic Geometry), Core Functional Layout (Functional Parts).
2. MUTABLE ELEMENTS: Surface Semantics, CMF (Color, Material, Finish), Micro-detailing, Lighting nuances.
3. LOGIC: Identify "Neighboring Semantics" for the current attributes.
4. MANDATE: Zero tolerance for silhouette shift. Zero tolerance for perspective drift.`;

const normalizeAspectRatio = (ratio?: string): string => {
  if (!ratio) return '1:1';
  if (VALID_ASPECT_RATIOS.includes(ratio)) return ratio;
  try {
    const [w, h] = ratio.split(':').map(Number);
    if (isNaN(w) || isNaN(h)) return '1:1';
    const numericRatio = w / h;
    const targets = [{ id: '1:1', val: 1 }, { id: '4:3', val: 4/3 }, { id: '3:4', val: 3/4 }, { id: '16:9', val: 16/9 }, { id: '9:16', val: 9/16 }];
    return targets.reduce((prev, curr) => Math.abs(curr.val - numericRatio) < Math.abs(prev.val - numericRatio) ? curr : prev).id;
  } catch (e) { return '1:1'; }
};

export const getClosestGeminiRatio = (width: number, height: number): string => {
    const ratio = width / height;
    const targets = [{ id: '1:1', val: 1 }, { id: '4:3', val: 4/3 }, { id: '3:4', val: 3/4 }, { id: '16:9', val: 16/9 }, { id: '9:16', val: 9/16 }];
    return targets.reduce((prev, curr) => Math.abs(curr.val - ratio) < Math.abs(prev.val - ratio) ? curr : prev).id;
};

