        if (usePro) await ensureApiKey();
        const ai = getAI(); 
        const model = usePro ? 'gemini-3-pro-image-preview' : 'gemini-2.5-flash-image';

        const sourceData = sourceBase64.split(',')[1] || sourceBase64;
        const sourceMime = sourceBase64.split(';')[0].split(':')[1] || 'image/jpeg';

        const parts: any[] = [
            { inlineData: { data: sourceData, mimeType: sourceMime } }
        ];

        if (maskBase64) {
            const maskData = maskBase64.split(',')[1] || maskBase64;
            // 采用 PNG 格式上传掩码，保留最高清晰度，无伪影
            parts.push({ inlineData: { data: maskData, mimeType: 'image/png' } });

            // 协议指令：明确告知 AI INPUT_FILE_0 是底图，INPUT_FILE_1 是空间约束掩码。
