            const sizeMando = `OUTPUT MANDATE: Match input physical aspect ratio of ${ratio} perfectly.`;
            parts.push({ text: `${MASKED_INPAINTING_PROTOCOL}${prompt}. ${sizeMando} FOCUS on pixel alignment. MAINTAIN 1K production quality.` });
        } else {
            parts.push({ text: `Modify the following image: ${prompt}.` });
        }

        const response = await ai.models.generateContent({ 
            model, 
            contents: [{ parts }], 
            config: { imageConfig: { aspectRatio: normalizeAspectRatio(ratio) } } 
        });
        const part = response.candidates?.[0]?.content?.parts?.find(p => p.inlineData); if (part?.inlineData) return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
        throw new Error("Edit failed.");
    });
