export const identifyPoint = async (base64: string, y: number, x: number, temperature: number = 0.8): Promise<string> => {
    return retryWithBackoff(async () => {
        const ai = getAI();
        const data = base64.split(',')[1] || base64;
        const mimeType = base64.split(';')[0].split(':')[1] || 'image/jpeg';

        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: [{
                parts: [
                    { inlineData: { data, mimeType } },
                    { text: `你是一个专业的视觉观察员。请观察图中归一化坐标 [y=${Math.round(y)}, x=${Math.round(x)}] 的物体。
                    请使用“带修饰语的中文短语”来描述。格式必须是：[修饰语] + [核心物体]。
                    当前解析深度(Temperature)为 ${temperature.toFixed(1)}。
                    - 若深度较低：描述应简洁明了（如：一个白色的按钮）。
                    - 若深度较高：描述应包含材质、光泽、状态或更细微的特征（如：一个带有拉丝纹理的银色金属按钮）。
                    限制在 12 字以内。` }
                ]
            }],
            config: { temperature }
        });
        return response.text?.trim() || "选定点位";
    });
};

// 自动识别图中所有关键视觉点位（解构模式）
export const detectAllPoints = async (base64: string, temperature: number = 0.8): Promise<{point: [number, number], label: string}[]> => {
    return retryWithBackoff(async () => {
        const ai = getAI();
        const data = base64.split(',')[1] || base64;
        const mimeType = base64.split(';')[0].split(':')[1] || 'image/jpeg';

        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: [{
                parts: [
                    { inlineData: { data, mimeType } },
                    { text: `你是一个工业设计视觉解构专家。请识别图中所有关键的视觉特征点（Anchor Points）。
                    1. 包含核心主体结构点及微小的细节特征。
                    2. 每个点必须包含精确的归一化 [y, x] 坐标 (范围 0-1000)。
                    3. label 必须采用“带修饰语的中文描述”，格式为：[修饰语] + [核心物体]。
                    4. 当前解析深度(Temperature)为 ${temperature.toFixed(1)}。
                       - 低深度：返回约 10 个核心点，描述简要。
                       - 高深度：返回 15 个以上点，包含极其细微的零件、光影转折或材质细节，描述应极具细节感（如：细磨砂质感的侧面接缝）。
                    5. 返回 JSON 数组。` }
                ]
            }],
            config: { 
                responseMimeType: "application/json",
                temperature: temperature, 
                responseSchema: {
                    type: Type.ARRAY,
                    items: {
                        type: Type.OBJECT,
                        properties: {
                            point: { 
                                type: Type.ARRAY, 
                                items: { type: Type.NUMBER },
                                description: "[y, x] coordinates from 0-1000"
                            },
                            label: { 
                                type: Type.STRING,
                                description: "Detailed descriptive phrase of the feature in Chinese"
                            }
                        },
                        required: ["point", "label"]
                    }
                }
            }
        });
        const parsed = JSON.parse(response.text);
        if (!Array.isArray(parsed)) throw new Error("Invalid output format");
        return parsed;
    });
};

