const VALID_ASPECT_RATIOS = ['1:1', '3:4', '4:3', '9:16', '16:9'];

const MASKED_INPAINTING_PROTOCOL = `[MASKED_RE-RENDERING_SYSTEM_V2]:
1. INPUT_FILE_0: SOURCE_IMAGE (Raw original).
2. INPUT_FILE_1: BINARY_MASK (White = Modify, Black = Protect).
3. INPUT_FILE_2: VISUAL_INTENT_GUIDE (Image with user scribbles/markers).
4. MANDATE: Use INPUT_FILE_2 to understand the SHAPE and STYLE of the requested change. 
5. SPATIAL CONSTRAINT: Use INPUT_FILE_1 as a strict pixel-by-pixel boundary.
6. ALIGNMENT: All 3 inputs are perfectly aligned in a 1024x1024 coordinate grid.
7. PROTECTION: Black pixels in INPUT_FILE_1 must remain 100% untouched. No perspective shift.
8. INSTRUCTION: `;

const normalizeAspectRatio = (ratio?: string): string => {
  if (!ratio) return '1:1';
  if (VALID_ASPECT_RATIOS.includes(ratio)) return ratio;
  return '1:1'; // 默认强制使用 1:1 容器以保证空间精度
};

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

/**
 * 核心预处理：将任意比例的图像放入 1:1 的标准 1024px 黑色容器中。
 * 这解决了 AI 侧拉伸导致的透视和对齐失效问题。
 */
const prepareStandardSquare = (base64: string): Promise<string> => {
    return new Promise((resolve) => {
        const img = new Image();
        img.crossOrigin = "anonymous";
        img.onload = () => {
            const canvas = document.createElement('canvas');
            canvas.width = 1024;
            canvas.height = 1024;
            const ctx = canvas.getContext('2d');
            if (!ctx) { resolve(base64); return; }

            ctx.fillStyle = '#000000';
            ctx.fillRect(0, 0, 1024, 1024);

            const ratio = img.width / img.height;
            let drawW, drawH;
            if (ratio >= 1) {
                drawW = 1024;
                drawH = 1024 / ratio;
            } else {
                drawH = 1024;
                drawW = 1024 * ratio;
            }

            const offsetX = (1024 - drawW) / 2;
            const offsetY = (1024 - drawH) / 2;
            ctx.drawImage(img, offsetX, offsetY, drawW, drawH);
            resolve(canvas.toDataURL('image/png'));
        };
        img.src = base64;
    });
};

export const editImage = async (sourceBase64: string, prompt: string, ratio: string, maskBase64?: string, visualGuideBase64?: string, usePro: boolean = true): Promise<string> => {
    return retryWithBackoff(async () => {
        const ai = getAI(); 
        const model = usePro ? 'gemini-3-pro-image-preview' : 'gemini-2.5-flash-image';

        // 1. 全部标准化为 1:1，解决畸变问题
        const squareSource = await prepareStandardSquare(sourceBase64);

        const parts: any[] = [
            { inlineData: { data: squareSource.split(',')[1], mimeType: 'image/png' } }
        ];

        if (maskBase64) {
            const squareMask = await prepareStandardSquare(maskBase64);
            parts.push({ inlineData: { data: squareMask.split(',')[1], mimeType: 'image/png' } });

            if (visualGuideBase64) {
                const squareGuide = await prepareStandardSquare(visualGuideBase64);
                parts.push({ inlineData: { data: squareGuide.split(',')[1], mimeType: 'image/png' } });
            }

            parts.push({ text: `${MASKED_INPAINTING_PROTOCOL}${prompt}. Maintain identical focal length and object scale. Zero tolerance for silhouette drift.` });
        } else {
            parts.push({ text: `Modify this image: ${prompt}` });
        }

        const response = await ai.models.generateContent({ 
            model, 
            contents: [{ parts }], 
            config: { imageConfig: { aspectRatio: '1:1' } } 
        });

        const part = response.candidates?.[0]?.content?.parts?.find(p => p.inlineData); 
        if (part?.inlineData) return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
        throw new Error("Edit failed.");
    });
};

async function retryWithBackoff<T>(operation: () => Promise<T>, retries = 3, delay = 2000): Promise<T> {
  try { return await operation(); } catch (error: any) {
    let errorStr = (typeof error === 'string' ? error : error.message || JSON.stringify(error)).toLowerCase();
    if (isRetryableError(errorStr) && retries > 0) { await sleep(delay); return retryWithBackoff(operation, retries - 1, delay * 2); }
    throw error;
  }
}
const isRetryableError = (s: string) => s.includes('overloaded') || s.includes('unavailable') || s.includes('429') || s.includes('500');

