const uncropFromSquare = (base64: string, originalW: number, originalH: number): Promise<string> => {
    return new Promise((resolve) => {
        const img = new Image();
        img.onload = () => {
            const canvas = document.createElement('canvas');
            canvas.width = originalW;
            canvas.height = originalH;
            const ctx = canvas.getContext('2d');
            if (!ctx) { resolve(base64); return; }

            const ratio = originalW / originalH;
            let sourceW, sourceH;
            if (ratio >= 1) {
                sourceW = 1024;
                sourceH = 1024 / ratio;
            } else {
                sourceH = 1024;
                sourceW = 1024 * ratio;
            }

            const sourceX = (1024 - sourceW) / 2;
            const sourceY = (1024 - sourceH) / 2;

            ctx.drawImage(img, sourceX, sourceY, sourceW, sourceH, 0, 0, originalW, originalH);
            resolve(canvas.toDataURL('image/png'));
        };
        img.src = base64;
    });
};

const compressImageForSync = (base64: string, maxDim: number = 800): Promise<string> => {
  return new Promise((resolve) => {
    if (!base64 || !base64.startsWith('data:image')) {
      resolve(base64);
      return;
    }
    const img = new Image();
    img.crossOrigin = "anonymous";
    img.onload = () => {
      let width = img.width;
      let height = img.height;
      if (width > height) {
        if (width > maxDim) { height *= maxDim / width; width = maxDim; }
      } else {
        if (height > maxDim) { width *= maxDim / height; height = maxDim; }
      }
      const canvas = document.createElement('canvas');
      canvas.width = width; canvas.height = height;
      const ctx = canvas.getContext('2d');
      if (!ctx) { resolve(base64); return; }
      ctx.drawImage(img, 0, 0, width, height);
      resolve(canvas.toDataURL('image/jpeg', 0.7));
    };
    img.onerror = () => resolve(base64);
    img.src = base64;
  });
};

const getClosestAspectRatio = (width: number, height: number): string => {
  const ratio = width / height;
  const targets = ASPECT_RATIOS.map(r => {
    const [w, h] = r.id.split(':').map(Number);
    return { id: r.id, val: w / h };
  });
  return targets.reduce((prev, curr) => Math.abs(curr.val - ratio) < Math.abs(prev.val - ratio) ? curr : prev).id;
};

