export const editImage = async (sourceBase64: string, prompt: string, ratio: string, maskBase64?: string, visualGuideBase64?: string, usePro: boolean = true): Promise<string> => {
    return retryWithBackoff(async () => {
        const ai = getAI(); 
        const model = usePro ? 'gemini-3-pro-image-preview' : 'gemini-2.5-flash-image';

        // 全部通过标准化容器对齐，防止空间偏移
        const squareSource = await standardizeToSquare(sourceBase64);
        const parts: any[] = [{ inlineData: { data: squareSource.split(',')[1], mimeType: 'image/png' } }];

        if (maskBase64) {
            const squareMask = await standardizeToSquare(maskBase64);
            parts.push({ inlineData: { data: squareMask.split(',')[1], mimeType: 'image/png' } });

            if (visualGuideBase64) {
                const squareGuide = await standardizeToSquare(visualGuideBase64);
                parts.push({ inlineData: { data: squareGuide.split(',')[1], mimeType: 'image/png' } });
            }

            const inpaintProtocol = `[PIXEL_PERFECT_GUIDED_INPAINTING]:
1. INPUT_FILE_0: Original Image.
2. INPUT_FILE_1: Binary Mask (White=Edit, Black=Lock).
3. INPUT_FILE_2: Visual Guide (User scribbles defining shape/intent).
MANDATE: Follow the scribbles in INPUT_FILE_2 to understand the morphology of the change.
CONSTRAINT: Strictly limit output to White regions of INPUT_FILE_1. Black regions are IMMUTABLE.
ZERO TOLERANCE: No perspective shift, no scale distortion.
INSTRUCTION: ${prompt}`;

            parts.push({ text: inpaintProtocol });
        } else {
            parts.push({ text: `Modify image: ${prompt}` });
        }

        const response = await ai.models.generateContent({ 
            model, 
            contents: [{ parts }], 
            config: { imageConfig: { aspectRatio: '1:1' } } 
        });

        const part = response.candidates?.[0]?.content?.parts?.find(p => p.inlineData); 
        if (part?.inlineData) return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
        throw new Error("Edit failed.");
    });
};

