async function retryWithBackoff<T>(operation: () => Promise<T>, retries = 3, delay = 2000): Promise<T> {
  try { return await operation(); } catch (error: any) {
    let errorStr = (typeof error === 'string' ? error : error.message || JSON.stringify(error)).toLowerCase();
    if (isRetryableError(errorStr) && retries > 0) { await sleep(delay); return retryWithBackoff(operation, retries - 1, delay * 2); }
    throw error;
  }
}
const isRetryableError = (s: string) => s.includes('overloaded') || s.includes('unavailable') || s.includes('429') || s.includes('500');

export const generateImage = async (prompt: string, styleSuffix: string, ratio: string, artisticScale: number = 50, resolution: string = '1K', spatial?: SpatialConfig, recipeInstruction?: string, usePro: boolean = false): Promise<string> => {
