const standardizeToSquare = (base64: string): Promise<string> => {
    return new Promise((resolve) => {
        const img = new Image();
        img.crossOrigin = "anonymous";
        img.onload = () => {
            const canvas = document.createElement('canvas');
            canvas.width = 1024; canvas.height = 1024;
            const ctx = canvas.getContext('2d');
            if (!ctx) { resolve(base64); return; }
            ctx.fillStyle = '#000000';
            ctx.fillRect(0, 0, 1024, 1024);
            const ratio = img.width / img.height;
            let drawW, drawH;
            if (ratio >= 1) { drawW = 1024; drawH = 1024 / ratio; } else { drawH = 1024; drawW = 1024 * ratio; }
            ctx.drawImage(img, (1024 - drawW) / 2, (1024 - drawH) / 2, drawW, drawH);
            resolve(canvas.toDataURL('image/png'));
        };
        img.src = base64;
    });
};

export const editImage = async (sourceBase64: string, prompt: string, ratio: string, maskBase64?: string, visualGuideBase64?: string, usePro: boolean = true): Promise<string> => {
    return retryWithBackoff(async () => {
        const ai = getAI(); 
        const model = usePro ? 'gemini-3-pro-image-preview' : 'gemini-2.5-flash-image';
        const squareSource = await standardizeToSquare(sourceBase64);
        const parts: any[] = [{ inlineData: { data: squareSource.split(',')[1], mimeType: 'image/png' } }];
        if (maskBase64) {
            const squareMask = await standardizeToSquare(maskBase64);
            parts.push({ inlineData: { data: squareMask.split(',')[1], mimeType: 'image/png' } });
            if (visualGuideBase64) {
                const squareGuide = await standardizeToSquare(visualGuideBase64);
                parts.push({ inlineData: { data: squareGuide.split(',')[1], mimeType: 'image/png' } });
            }
            const inpaintProtocol = `[PIXEL_PERFECT_GUIDED_INPAINTING]:
MANDATE: Follow the scribbles in INPUT_FILE_2 to understand shape/intent.
CONSTRAINT: strictly White regions of INPUT_FILE_1. Black regions are IMMUTABLE.
ZERO TOLERANCE: No perspective shift or scale distortion.
INSTRUCTION: ${prompt}`;
            parts.push({ text: inpaintProtocol });
        } else { parts.push({ text: `Modify image: ${prompt}` }); }
        const response = await ai.models.generateContent({ model, contents: [{ parts }], config: { imageConfig: { aspectRatio: '1:1' } } });
        const part = response.candidates?.[0]?.content?.parts?.find(p => p.inlineData); 
        if (part?.inlineData) return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
        throw new Error("Edit failed.");
    });
};

