                <button onClick={() => fileInputRef.current?.click()} className="w-full flex items-center gap-3 px-4 py-3 text-[10px] font-black text-zinc-400 hover:text-white hover:bg-white/5 rounded-xl transition-all uppercase tracking-widest"><UploadIcon className="w-4 h-4" /> 导入 JSON</button>
                <button onClick={onExport} className="w-full flex items-center gap-3 px-4 py-3 text-[10px] font-black text-zinc-400 hover:text-white hover:bg-white/5 rounded-xl transition-all uppercase tracking-widest"><DownloadIcon className="w-4 h-4" /> 导出 JSON</button>
