        <div className="w-px h-6 bg-white/5 mx-2" />
        <div className="flex items-center gap-1.5">
            <button onClick={() => handleCloudAction('upload')} disabled={isCloudSyncing} className={`flex items-center gap-2.5 px-5 py-2.5 rounded-full transition-all active:scale-95 shadow-lg ${syncStatus === 'saving' ? 'bg-indigo-600 text-white animate-pulse' : 'bg-indigo-600/10 text-indigo-400 border border-indigo-500/20 hover:bg-indigo-600/20'}`}>
              {syncStatus === 'saving' ? <RefreshIcon className="w-3.5 h-3.5 animate-spin" /> : <CloudUploadIcon className="w-3.5 h-3.5" />}
              <span className="text-[10px] font-black uppercase tracking-[0.15em] whitespace-nowrap">{syncStatus === 'saving' ? '备份中...' : '备份到云'}</span>
            </button>
            <button onClick={() => handleCloudAction('download')} disabled={isCloudSyncing} className={`flex items-center gap-2.5 px-5 py-2.5 rounded-full transition-all active:scale-95 ${syncStatus === 'loading' ? 'bg-white text-black animate-pulse' : 'bg-white/5 text-zinc-400 hover:bg-white/10 hover:text-white'}`}>
              {syncStatus === 'loading' ? <RefreshIcon className="w-3.5 h-3.5 animate-spin" /> : <CloudDownloadIcon className="w-3.5 h-3.5" />}
              <span className="text-[10px] font-black uppercase tracking-[0.15em] whitespace-nowrap">{syncStatus === 'loading' ? '拉取中...' : '同步云端'}</span>
            </button>
        </div>
      </div>
      <input type="file" ref={fileInputRef} onChange={handleFileChange} className="hidden" accept=".json" />
    </div>
  );
};
