const uncropFromSquare = (base64: string, originalW: number, originalH: number): Promise<string> => {
    return new Promise((resolve) => {
        const img = new Image();
        img.onload = () => {
            const canvas = document.createElement('canvas');
            canvas.width = originalW; canvas.height = originalH;
            const ctx = canvas.getContext('2d');
            if (!ctx) { resolve(base64); return; }
            const ratio = originalW / originalH;
            let sourceW, sourceH;
            if (ratio >= 1) { sourceW = 1024; sourceH = 1024 / ratio; } else { sourceH = 1024; sourceW = 1024 * ratio; }
            ctx.drawImage(img, (1024 - sourceW) / 2, (1024 - sourceH) / 2, sourceW, sourceH, 0, 0, originalW, originalH);
            resolve(canvas.toDataURL('image/png'));
        };
        img.src = base64;
    });
};

const App: React.FC = () => {
  const { items, setItems, commit, undo, redo, resetHistory } = useHistory([]);
  const [selection, setSelection] = useState<string[]>([]);
  const [view, setView] = useState<ViewState>({ x: 0, y: 0, scale: 1 });

  const [tool, setTool] = useState<ToolType>('select');
  const [showLayers, setShowLayers] = useState(false);
  const [showHistory, setShowHistory] = useState(false);
  const [contextMenu, setContextMenu] = useState<{ isOpen: boolean; x: number; y: number; itemId?: string } | null>(null);
  const [externalRefImage, setExternalRefImage] = useState<string | null>(null);
  const [quickLookItem, setQuickLookItem] = useState<CanvasItem | null>(null);
  const [isPropertiesPanelOpen, setIsPropertiesPanelOpen] = useState(false);
  const [showTopologyWheel, setShowTopologyWheel] = useState(false);
  const [topologyTargetId, setTopologyTargetId] = useState<string | null>(null);
  const [propertyPanelView, setPropertyPanelView] = useState<{view: string, ts: number} | null>(null);
  const [editMode, setEditMode] = useState(false);
  const [editTool, setEditTool] = useState<EditToolType>('brush');
  const [brushSize, setBrushSize] = useState(30);
  const [isPickingPoint, setIsPickingPoint] = useState(false);
  const [expressionState, setExpressionState] = useState<ExpressionState>({ itemId: '', isOpen: false });
  const [inferenceState, setInferenceState] = useState({ itemId: '', isOpen: false });
  const [isCncMode, setIsCncMode] = useState(false);
  const [isChatPanelExpanded, setIsChatPanelExpanded] = useState(false);

  const captureState = useCaptureManager();
  const { isCapturing, captureRect, showCaptureMenu, grabScreenPixels, resetCapture } = captureState;
  const { annotations, activeTool: activeAnnoTool, setActiveTool: setActiveAnnoTool } = useAnnotations();

  const { handleFile, handlePaste, findPlacementSpot, getImageDimensions } = useAssetManager({ view, items, setItems, setSelection });
  useProjectPersistence(items, (loadedItems) => { resetHistory(loadedItems); });

  const canvasRef = useRef<CanvasRef>(null);
  const chatRef = useRef<GeminiChatPanelRef>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const selectedItem = selection.length === 1 ? items.find(it => it.id === selection[0]) || null : null;
  const selectedItems = items.filter(it => selection.includes(it.id));

  const handleUpdateItem = useCallback((id: string, updates: Partial<CanvasItem>) => setItems(prev => prev.map(item => item.id === id ? { ...item, ...updates } : item)), [setItems]);
  const handleDeleteItems = useCallback((ids: string[]) => { const nextItems = items.filter(item => !ids.includes(item.id)); setItems(nextItems); commit(nextItems); setSelection([]); }, [items, setItems, commit]);

  const centerOnItem = useCallback((item: CanvasItem, targetScale?: number) => {
    const scale = targetScale || Math.min(view.scale, 1.0);
    const leftPanelWidth = (showLayers || showHistory) ? 224 + 80 : 80;
    const rightPanelWidth = isPropertiesPanelOpen ? 320 : 80;
    const availableWidth = window.innerWidth - leftPanelWidth - rightPanelWidth;
    const centerX = leftPanelWidth + availableWidth / 2;
    const centerY = window.innerHeight / 2;
    setView({ scale, x: centerX - (item.x + item.width / 2) * scale, y: centerY - (item.y + item.height / 2) * scale });
  }, [view.scale, showLayers, showHistory, isPropertiesPanelOpen, setView]);

  const zoomToFit = useCallback(() => {
    if (items.length === 0) { setView({ x: 0, y: 0, scale: 1 }); return; }
    const minX = Math.min(...items.map(i => i.x)), minY = Math.min(...items.map(i => i.y));
    const maxX = Math.max(...items.map(i => i.x + i.width)), maxY = Math.max(...items.map(i => i.y + i.height));
    const contentWidth = maxX - minX, contentHeight = maxY - minY;
    const padding = 100;
    const leftPanelWidth = (showLayers || showHistory) ? 224 + 80 : 80;
    const rightPanelWidth = isPropertiesPanelOpen ? 320 : 80;
    const availableWidth = window.innerWidth - leftPanelWidth - rightPanelWidth - padding * 2;
    const availableHeight = window.innerHeight - padding * 2;
    const scale = Math.min(availableWidth / contentWidth, availableHeight / contentHeight, 1.5);
    const centerX = leftPanelWidth + (window.innerWidth - leftPanelWidth - rightPanelWidth) / 2;
    const centerY = window.innerHeight / 2;
    setView({ scale, x: centerX - (minX + contentWidth / 2) * scale, y: centerY - (minY + contentHeight / 2) * scale });
  }, [items, showLayers, showHistory, isPropertiesPanelOpen, setView]);

  const handleAddToCanvas = useCallback(async (base64: string, promptText?: string, refId?: string) => {
    const { width, height } = await getImageDimensions(base64);
    const displayWidth = 512;
    const displayHeight = (height * displayWidth) / width;
    const spot = findPlacementSpot(displayWidth, displayHeight, items);
    const newItem: CanvasItem = { id: crypto.randomUUID(), type: ItemType.IMAGE, x: spot.x, y: spot.y, width: displayWidth, height: displayHeight, rotation: 0, content: base64, status: 'generated', prompt: promptText || '', aspectRatio: getClosestGeminiRatio(width, height), links: refId ? [refId] : [] };
    const newItems = [...items, newItem];
    setItems(newItems); commit(newItems); setSelection([newItem.id]); centerOnItem(newItem);
  }, [items, findPlacementSpot, getImageDimensions, commit, setItems, setSelection, centerOnItem]);

  const handleGenerate = async (id: string, overridePrompt?: string, settings?: Partial<GenerationSettings>, manualRefs?: string[]) => {
    const sourceItem = id ? items.find(i => i.id === id) : null; 
    let contextItem: CanvasItem | null = id ? (sourceItem || null) : null;
    const { tasks } = parseGenerationIntent(overridePrompt || '', contextItem, settings);

    let targetW = contextItem?.width || 512;
    let targetH = contextItem?.height || 512;
    let ratioToUse = contextItem?.aspectRatio || settings?.ratio || '1:1';

    const styleId = settings?.style || 'industrial'; 
    const styleObj = STYLES.find(s => s.id === styleId) || STYLES[1];
    const usePro = settings?.usePro ?? true;

    let currentTempItems = [...items];
    tasks.forEach((t) => {
        const spot = findPlacementSpot(targetW, targetH, currentTempItems, contextItem);
        const placeholder: CanvasItem = { id: t.nid, type: ItemType.IMAGE, x: spot.x, y: spot.y, width: targetW, height: targetH, rotation: contextItem?.rotation || 0, content: '', status: 'loading', prompt: t.prompt, aspectRatio: ratioToUse, links: contextItem ? [contextItem.id] : [], engine: usePro ? 'Gemini 3 Pro' : 'Flash 2.5' };
        currentTempItems.push(placeholder);
    });
    setItems(currentTempItems); commit(currentTempItems); setSelection(tasks.map(t => t.nid));

    tasks.forEach(async (task) => {
        try {
            let url: string;
            if (contextItem && contextItem.content) { 
                url = await generateWithReferences(task.prompt, [{ label: 'Source', base64: contextItem.content }], ratioToUse, styleObj.promptSuffix, 50, '1K', undefined, undefined, task.infCfg, usePro); 
            } else { 
                url = await generateImage(task.prompt, styleObj.promptSuffix, ratioToUse, 50, '1K', undefined, undefined, usePro); 
            }
            setItems(prev => prev.map(i => i.id === task.nid ? { ...i, content: url, status: 'generated' } : i));
        } catch (e) { setItems(prev => prev.map(i => i.id === task.nid ? { ...i, status: 'error' } : i)); }
    });
  };

  const handleTopologyConfirm = async (strategies: string[]) => {
      if (!topologyTargetId) return;
      const target = items.find(it => it.id === topologyTargetId);
      if (!target?.content) return;

      setShowTopologyWheel(false);
      const nid = crypto.randomUUID();
      const spot = findPlacementSpot(target.width, target.height, items, target);
      const placeholder: CanvasItem = { ...target, id: nid, x: spot.x, y: spot.y, content: '', status: 'loading', links: [target.id], engine: 'Gemini 3 Pro' };

      setItems(prev => [...prev, placeholder]); commit([...items, placeholder]); setSelection([nid]);

      try {
          const styleObj = STYLES[1];
          const rawUrl = await generateTopologyVariation(target.content, target.aspectRatio || '1:1', styleObj.promptSuffix, strategies, true);
          const fixedUrl = await uncropFromSquare(rawUrl, target.width, target.height);
          setItems(prev => prev.map(i => i.id === nid ? { ...i, content: fixedUrl, status: 'generated' } : i));
      } catch (e) { setItems(prev => prev.map(i => i.id === nid ? { ...i, status: 'error' } : i)); }
  };

  const handleFloatingAction = (id: string, action: string) => {
    const item = items.find(it => it.id === id); if (!item) return;
    switch(action) {
      case 'variation': setTopologyTargetId(id); setShowTopologyWheel(true); break;
      case 'edit': setEditMode(true); setIsPropertiesPanelOpen(true); break;
      case 'delete': handleDeleteItems(selection); break;
      case 'inference': setInferenceState({ itemId: id, isOpen: true }); break;
      case 'expression': setExpressionState({ itemId: id, isOpen: true }); break;
    }
  };

  return (
    <div className="w-screen h-screen bg-[#f4f4f5] dark:bg-[#09090b] overflow-hidden flex flex-col font-sans relative" onDragOver={e => e.preventDefault()} onDrop={e => { e.preventDefault(); const fs = Array.from(e.dataTransfer.files || []); fs.forEach(f => handleFile(f)); }}>
      <TopBar onExport={() => {}} onImport={handleFile} onCloudExport={() => uploadProjectToCloud({ version: '1.1', timestamp: Date.now(), items, view })} onCloudImport={async () => { const pkg = await downloadProjectFromCloud(); resetHistory(pkg.items); setView(pkg.view); return; }} onNewProject={() => { if(window.confirm("确定新建项目？")) { resetHistory([]); setSelection([]); setView({x:0,y:0,scale:1}); } }} />
      <LeftToolbar activeTool={tool} setTool={setTool} onUpload={() => fileInputRef.current?.click()} onToggleLayers={() => setShowLayers(!showLayers)} showLayers={showLayers} onToggleHistory={() => setShowHistory(!showHistory)} showHistory={showHistory} recordingStatus='idle' onStartRecording={()=>{}} onStopRecording={()=>{}} onPauseRecording={()=>{}} onResumeRecording={()=>{}} recordingTime={0} />
      <LayersPanel isOpen={showLayers} items={items} selection={selection[0]} onSelectItem={id => { setSelection([id]); const it = items.find(i => i.id === id); if(it) centerOnItem(it); }} onUpdateItem={handleUpdateItem} />
      <HistoryPanel isOpen={showHistory} onClose={() => setShowHistory(false)} onRestore={s => { resetHistory(s.items); setSelection([]); }} />

      <div className="w-full h-full">
        <Canvas ref={canvasRef} items={items} selection={selection} tool={tool} view={view} setView={setView} setSelection={setSelection} addItem={it => { setItems([...items, it]); commit([...items, it]); }} updateItem={handleUpdateItem} editMode={editMode} editTool={editTool} brushSize={brushSize} onSelectItem={id => { const it = items.find(i => i.id === id); if(it) setQuickLookItem(it); }} onFloatingAction={handleFloatingAction} expressionState={expressionState} setExpressionState={setExpressionState} inferenceState={inferenceState} setInferenceState={setInferenceState} />
      </div>

      <div className={`fixed right-4 top-4 bottom-4 flex flex-col items-end transition-all duration-500 ${isPropertiesPanelOpen ? 'w-80' : 'w-16'}`}>
        {!isPropertiesPanelOpen && <button onClick={() => setIsPropertiesPanelOpen(true)} className="w-14 h-14 rounded-full bg-[#09090b] border border-zinc-800 text-indigo-400 flex items-center justify-center shadow-2xl hover:scale-110 transition-all"><SlidersIcon className="w-6 h-6" /></button>}
        <div className={`flex-1 w-full overflow-hidden transition-all duration-500 ${isPropertiesPanelOpen ? 'scale-100 opacity-100' : 'scale-90 opacity-0 pointer-events-none'}`}>
          <PropertiesPanel selectedItem={selectedItem} selectedItems={selectedItems} onUpdateItem={handleUpdateItem} onGenerate={handleGenerate} onDelete={handleDeleteItems} onEnterEditMode={() => setEditMode(true)} onExitEditMode={() => setEditMode(false)} onFloatingAction={handleFloatingAction} isCncMode={isCncMode} setIsCncMode={setIsCncMode} />
        </div>
      </div>

      {showTopologyWheel && <TopologyWheel onConfirm={handleTopologyConfirm} onClose={() => setShowTopologyWheel(false)} />}
      <GeminiChatPanel ref={chatRef} onAddToCanvas={handleAddToCanvas} onExpandChange={setIsChatPanelExpanded} />
      <input type="file" ref={fileInputRef} onChange={e => { const fs = Array.from(e.target.files || []); fs.forEach(f => handleFile(f)); }} multiple className="hidden" />
    </div>
  );
};
export default App;
